def spiral(grid):
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    seed=[(i,j) for i in range(h) for j in range(w) if g[i][j] not in (0,2)]
    i,j=seed[0]; c=g[i][j]
    dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    drawn={(i,j)}
    for k in range(40):
        di,dj=dirs[k%4]; L=2*(k//2+1)
        for _ in range(L):
            i,j=i+di,j+dj
            if 0<=i<h and 0<=j<w:
                if g[i][j]==2: return g
                if (i,j) not in drawn: g[i][j]=c; drawn.add((i,j))
    return g
